<script lang="ts">

  import CommunityIcon from "./CommunityIcon.svelte";
  import { openUrl } from '@tauri-apps/plugin-opener';
  import UiIcon from './UiIcon.svelte';
  import HostingOptions from './HostingOptions.svelte';
  import CommunitySpotlight from './CommunitySpotlight.svelte';

  type Group = 'all' | 'skins' | 'building' | 'maps' | 'knowledge' | 'content';
  type Tool = { name: string; domain: string; url: string; group: Group; icon: string; description: string; detail: string; originalIcon?: boolean };
  const groups: { id: Group; label: string; icon: string }[] = [
    { id: 'all', label: 'Todas', icon: 'grid' }, { id: 'skins', label: 'Skins', icon: 'user' },
    { id: 'building', label: 'Creación', icon: 'cube' }, { id: 'maps', label: 'Mapas', icon: 'folder' },
    { id: 'knowledge', label: 'Guías', icon: 'terminal' }, { id: 'content', label: 'Contenido', icon: 'download' },
  ];
  const tools: Tool[] = [
    { name: 'NameMC', domain: 'namemc.com', url: 'https://namemc.com/minecraft-skins', group: 'skins', icon: 'user', description: 'Encuentra una nueva skin para tu próxima aventura.', detail: 'Catálogo de skins y perfiles de jugadores' },
    { name: 'SkinMC', domain: 'skinmc.net', url: 'https://skinmc.net/', group: 'skins', icon: 'image', description: 'Explora diseños de la comunidad y personaliza tu personaje.', detail: 'Skins y herramientas para tu identidad' },
    { name: 'Blockbench', domain: 'blockbench.net', url: 'https://www.blockbench.net/', group: 'building', icon: 'cube', description: 'Da forma a tus propias ideas con un editor de modelos 3D.', detail: 'Modelado, texturas y animaciones' },
    { name: 'MCStacker', domain: 'mcstacker.net', url: 'https://mcstacker.net/', group: 'building', icon: 'terminal', description: 'Crea comandos para entidades, objetos y bloques de Java Edition.', detail: 'Generador de comandos de Minecraft' },
    { name: 'Chunkbase', domain: 'chunkbase.com', url: 'https://www.chunkbase.com/apps/seed-map', group: 'maps', icon: 'grid', description: 'Explora biomas y estructuras a partir de la semilla de tu mundo.', detail: 'Elige la edición y la versión de tu mundo' },
    { name: 'Planet Minecraft', domain: 'planetminecraft.com', url: 'https://www.planetminecraft.com/', group: 'maps', icon: 'folder', description: 'Descubre construcciones, mapas, skins y recursos de otros creadores.', detail: 'Proyectos compartidos por la comunidad' },
    { name: 'Minecraft Wiki', domain: 'minecraft.wiki', url: 'https://minecraft.wiki/', group: 'knowledge', icon: 'terminal', description: 'Consulta bloques, recetas, criaturas y mecánicas del juego.', detail: 'Enciclopedia mantenida por la comunidad' },
    { name: 'Modrinth', domain: 'modrinth.com', url: 'https://modrinth.com/', group: 'content', icon: 'download', description: 'Explora mods, modpacks, shaders y paquetes de recursos.', detail: 'Descubre proyectos y sus creadores' },
    { name: 'CurseForge', domain: 'curseforge.com', url: 'https://www.curseforge.com/minecraft', group: 'content', icon: 'download', description: 'Encuentra contenido para construir una experiencia a tu medida.', detail: 'Mods, modpacks y recursos para Minecraft' },
    { name: 'Misode', domain: 'misode.github.io', url: 'https://misode.github.io/', group: 'building', icon: 'sliders', description: 'Prepara datapacks con generadores de recetas, loot tables y otros archivos.', detail: 'Generadores de datos por versión de Minecraft', originalIcon: true },
    { name: 'Minecraft Tools', domain: 'minecraft.tools', url: 'https://minecraft.tools/', group: 'building', icon: 'plugins', description: 'Diseña estandartes, fuegos artificiales, textos y comandos personalizados.', detail: 'Herramientas de creación y personalización', originalIcon: true },
    { name: 'GamerGeeks', domain: 'gamergeeks.net', url: 'https://www.gamergeeks.net/apps/minecraft', group: 'building', icon: 'terminal', description: 'Genera comandos para objetos, criaturas y construcciones con opciones visuales.', detail: 'Generadores give, summon y setblock', originalIcon: true },
    { name: 'Modpack Index', domain: 'modpackindex.com', url: 'https://www.modpackindex.com/', group: 'content', icon: 'filter', description: 'Encuentra packs por sus mods, versión del juego y otras características.', detail: 'Buscador y comparador de modpacks', originalIcon: true },
    { name: 'McSrvStat', domain: 'mcsrvstat.us', url: 'https://mcsrvstat.us/', group: 'knowledge', icon: 'server', description: 'Consulta el estado, mensaje y jugadores que publica un servidor.', detail: 'Herramienta externa de estado de servidores', originalIcon: true },
  ];
  let group = $state<Group>('all');
  let query = $state('');
  let opening = $state('');
  let message = $state('');
  const normalize = (value: string) => value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  let visible = $derived(tools.filter(tool => (group === 'all' || tool.group === group) && normalize(`${tool.name} ${tool.description} ${tool.detail}`).includes(normalize(query.trim()))));
  async function visit(tool: Tool) {
    if (opening) return;
    opening = tool.name; message = '';
    try { await openUrl(tool.url); }
    catch { message = `No se pudo abrir ${tool.name}. Puedes visitar ${tool.url} desde tu navegador.`; }
    finally { opening = ''; }
  }
</script>

<div class="community-workspace">
  <header class="community-heading"><div><span class="eyebrow">HECHO POR LA COMUNIDAD, PARA LA COMUNIDAD</span><h2>Más allá del mundo.</h2><p>Herramientas de la comunidad. Se abren en tu navegador.</p></div><div class="tool-count"><UiIcon name="compass" size={28}/><div><strong>{tools.length}</strong><span>lugares para explorar</span></div></div></header>
  <section class="community-intro" aria-labelledby="community-intro-title"><div class="intro-symbol" aria-hidden="true"><UiIcon name="grid" size={36}/></div><div><span class="eyebrow">TU PRÓXIMA IDEA EMPIEZA AQUÍ</span><h3 id="community-intro-title">Construye. Personaliza. Comparte.</h3><p>Un punto de encuentro con los proyectos que hacen crecer Minecraft.</p></div><span class="intro-marker" aria-hidden="true">01 / EXPLORAR</span></section>
  <div class="community-toolbar"><div class="category-filters" aria-label="Filtrar herramientas por categoría">{#each groups as category}<button class:active={group === category.id} aria-pressed={group === category.id} onclick={() => group = category.id}><UiIcon name={category.icon} size={15}/>{category.label}</button>{/each}</div><label class="search-field"><span class="sr-only">Buscar una herramienta</span><input type="search" bind:value={query} placeholder="Buscar una herramienta…"/></label></div>
  {#if message}<div class="open-error" role="alert">{message}</div>{/if}
  <p class="result-count" aria-live="polite">{visible.length} {visible.length === 1 ? 'herramienta disponible' : 'herramientas disponibles'}</p>
  <div class="tools-grid">{#each visible as tool}<article class="tool-card"><div class="tool-top"><div class="tool-symbol" aria-hidden="true"><CommunityIcon name={tool.name} domain={tool.domain} size={32}/></div><span class="tool-category">{groups.find(category => category.id === tool.group)?.label}</span></div><h3>{tool.name}</h3><span class="tool-domain">{tool.domain}</span><p>{tool.description}</p><div class="tool-bottom"><span>{tool.detail}</span><button onclick={() => visit(tool)} disabled={!!opening} aria-label={`Abrir ${tool.name} en el navegador`}>{opening === tool.name ? 'Abriendo…' : 'Explorar'}<UiIcon name="external" size={14}/></button></div></article>{:else}<div class="empty-state"><UiIcon name="grid" size={32}/><h3>No encontramos esa herramienta</h3><p>Prueba otro nombre o explora todas las categorías.</p><button onclick={() => { query = ''; group = 'all'; }}><UiIcon name="grid" size={15}/>Mostrar todas</button></div>{/each}</div>
  <HostingOptions compact/>
  <CommunitySpotlight placement="community"/>
  <footer>Enlaces a los sitios de sus respectivos creadores y comunidades.</footer>
</div>

<style>
