.community-toolbar{display:flex;gap:16px;align-items:center;justify-content:space-between;flex-wrap:wrap}.category-filters{display:flex;gap:7px;flex-wrap:wrap}.category-filters button{display:flex;align-items:center;gap:7px;border:1px solid #ffffff19;color:#aebcba;background:rgba(var(--bg-base-rgb,12,20,20),.6);border-radius:4px;padding:10px 12px;font-family:inherit;font-size:.74rem;font-weight:600;cursor:pointer;min-height:39px}.category-filters button.active{color:var(--primary,#7fdbac);border-color:var(--primary,#7fdbac);background:rgba(var(--primary-rgb,77,205,142),.1);box-shadow:inset 0 -2px var(--primary,#7fdbac)}.category-filters button:hover{border-color:var(--primary,#7fdbac)}.search-field{flex:1;max-width:290px;min-width:180px}.search-field input{width:100%;box-sizing:border-box;border:1px solid #ffffff24;border-radius:4px;padding:11px 13px;background:rgba(var(--bg-base-rgb,12,20,20),.85);color:#e6efeb;font:inherit;font-size:.78rem}.search-field input::placeholder{color:#859892}.result-count{color:#91a29e;font-size:.72rem;margin:-6px 0 -10px}.tools-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,270px),1fr));gap:17px}.tool-card{display:flex;flex-direction:column;min-width:0;padding:22px;border:1px solid #ffffff17;border-radius:6px;background:rgba(var(--bg-base-rgb,12,20,20),.83);backdrop-filter:blur(var(--blur-px,12px));box-shadow:inset 0 1px #ffffff05,0 8px 20px #0001;transition:border-color .18s,transform .18s}.tool-card:hover{border-color:rgba(var(--primary-rgb,77,205,142),.52);transform:translateY(-2px)}.tool-top{display:flex;justify-content:space-between;align-items:flex-start;gap:14px}.tool-symbol{display:grid;place-items:center;width:47px;height:47px;border:1px solid rgba(var(--primary-rgb,77,205,142),.22);background:rgba(var(--primary-rgb,77,205,142),.08);color:#c3ccd8;box-shadow:inset 2px 2px #ffffff05,inset -2px -2px #0003}.tool-category{font-size:.62rem;padding:5px 7px;color:#9babaa;border:1px solid #ffffff12;border-radius:3px}.tool-card h3{font:700 1.1rem var(--font-display,'Consolas',monospace);color:#eaf2f0;margin:20px 0 7px}.tool-domain{font:400 .68rem var(--font-display,'Consolas',monospace);color:var(--primary,#7fdbac)}.tool-card p{font-size:.8rem;line-height:1.75;color:#a7b6b2;margin:17px 0 23px;flex:1}.tool-bottom{display:grid;gap:16px;border-top:1px solid #ffffff0e;padding-top:15px}.tool-bottom>span{font-size:.65rem;line-height:1.5;color:#849b93}.tool-bottom button,.empty-state button{display:flex;justify-content:space-between;align-items:center;gap:12px;border:1px solid rgba(var(--primary-rgb,77,205,142),.42);border-radius:4px;padding:10px 12px;background:rgba(var(--primary-rgb,77,205,142),.13);box-shadow:inset 0 2px #ffffff08,inset 0 -2px #0003;color:#e9f5ee;font:600 .75rem var(--font-display,'Consolas',monospace);cursor:pointer}.tool-bottom button:hover:enabled,.empty-state button:hover{background:rgba(var(--primary-rgb,77,205,142),.23);border-color:var(--primary,#7fdbac)}.tool-bottom button:disabled{opacity:.5;cursor:wait}.community-workspace button:focus-visible,.search-field input:focus-visible{outline:2px solid var(--primary,#7fdbac);outline-offset:3px}.open-error{padding:14px 17px;border:1px solid #ff9a9a55;border-radius:4px;background:#a326291c;color:#ffbeb6;font-size:.8rem;line-height:1.6;overflow-wrap:anywhere}.empty-state{grid-column:1/-1;display:grid;justify-items:center;text-align:center;gap:12px;border:1px dashed #ffffff23;border-radius:6px;padding:50px 20px;color:#a0b4ad}.empty-state h3{margin:0;color:#d2e3dc;font-size:1rem}.empty-state p{margin:0;font-size:.8rem}.empty-state button{margin-top:8px}.community-workspace footer{font-size:.68rem;color:#8e9e98;border-top:1px solid #ffffff11;padding-top:17px}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@media(max-width:700px){.community-intro{padding:20px;gap:15px}.intro-symbol{width:49px;height:49px}.intro-marker{display:none}.community-intro h3{font-size:1.03rem}.search-field{max-width:none;flex-basis:100%}.tool-count{display:none}.category-filters button{padding:9px 10px}.community-heading h2{font-size:1.65rem}}@media(prefers-reduced-motion:reduce){.tool-card{transition:none}.tool-card:hover{transform:none}}
